import { test } from 'node:test'
import assert from 'node:assert'
import { NODE_STATE_TRANSITIONS, STAGE_STATE_TRANSITIONS } from './lifecycleTypes.ts'


test('COMPLETED node state can transition to REWORK', () => {
  const transitions = [...NODE_STATE_TRANSITIONS.COMPLETED]
  assert.ok(
    transitions.includes('REWORK'),
    'COMPLETED should allow transition to REWORK'
