import { test } from 'node:test'
import assert from 'node:assert'
import { NODE_STATE_TRANSITIONS, STAGE_STATE_TRANSITIONS } from './lifecycleTypes.ts'


test('REWORK node state exists and can transition to ENTERING', () => {
  assert.ok(
    'REWORK' in NODE_STATE_TRANSITIONS,
    'REWORK state should exist in node transition table'
  )
  const transitions = [...(NODE_STATE_TRANSITIONS as any).REWORK]
  assert.ok(
    transitions.includes('ENTERING'),
    'REWORK should allow transition to ENTERING'
  )
})


test('PENDING node state still transitions to ENTERING (unchanged behavior)', () => {
  const transitions = [...NODE_STATE_TRANSITIONS.PENDING]
  assert.ok(transitions.includes('ENTERING'))
})


test('FAILED node state remains terminal (unchanged behavior)', () => {
  assert.deepStrictEqual([...NODE_STATE_TRANSITIONS.FAILED], [])
})


test('STAGE COMPLETED remains terminal (stages do not support rework)', () => {
  assert.deepStrictEqual([...STAGE_STATE_TRANSITIONS.COMPLETED], [])
})
